select * from TBL_Group_TESTPLAN where 1=1

	AND planname LIKE concat(concat('%',#{queryParam.planname}),'%')


	AND plannumber LIKE concat(concat('%',#{queryParam.plannumber}),'%')


	AND planyear LIKE concat(concat('%',#{queryParam.planyear}),'%')


	AND status LIKE concat(concat('%',#{queryParam.status}),'%')


	AND toIssued =#{queryParam.toIssued}


	AND ISSUED_STAFFID  LIKE concat(concat('%',#{queryParam.issuedStaffid}),'%')


	and starttime >=#{queryParam.starttime}


	and endtime <=#{queryParam.endtime}


	AND creatid=#{queryParam.creatid}


	and orgid IN

		#{item}




	${sql}

order by id desc
